+import { createAPI } from "./src/core/api.ts";
+import type { Record } from "./src/core/project.ts";
+
+const api = createAPI();
+
+// Example 1: Hook-based usage (unchanged from original)
+const hookInjection = () => {
+  const injected = api.injectRecords("my-repo", "src/main.ts");
+  if (injected) {
+    console.log("Context to inject:", injected);
+  }
+};
+
+// Example 2: User WITHOUT a hook reports tool usage
+const userWithoutHook = () => {
+  const repo = "my-repo";
+
+  const mockLookupRecords = (repo: string, paths: string[]): Record[] => [
+    {
+      path: "src/main.ts",
+      commits: [
+        {
+          hash: "abc123def456",
+          message: "Add feature X",
+          author: "Alice",
+          date: new Date("2024-01-15"),
+        },
+      ],
+    },
+  ];
+
+  // Step 1: Report that a Read tool was used
+  api.reportToolExecution(
+    repo,
+    {
+      toolName: "Read",
+      params: { file_path: "src/main.ts" },
+    },
+    mockLookupRecords
+  );
+
+  // Step 2: Query for records about that file
+  const records = api.queryRecords(repo, "src/main.ts");
+  console.log("Records for src/main.ts:", records);
+};
+
+// Example 3: Bash command parsing
+const bashCommandExample = () => {
+  const mockLookupRecords = (repo: string, paths: string[]): Record[] => [];
+
+  api.reportToolExecution(
+    "my-repo",
+    {
+      toolName: "Bash",
+      params: {
+        command: "grep -r 'TODO' src/",
+      },
+    },
+    mockLookupRecords
+  );
+
+  // Records for "src/" are now stored
+  const records = api.queryRecords("my-repo", "src/");
+  console.log("Records found via grep:", records);
+};
+
+// Example 4: Batch query for multiple files
+const batchQuery = () => {
+  const records = api.queryRecordsBatch("my-repo", [
+    "src/main.ts",
+    "src/utils.ts",
+    "src/types.ts",
+  ]);
+
+  records.forEach((fileRecords, filePath) => {
+    console.log(`${filePath}:`, fileRecords);
+  });
+};
+
+// Example 5: Using the middleware wrapper (for agents)
+const withMiddleware = async () => {
+  const { withRecordContext } = await import("./src/integration/tool-middleware.ts");
+
+  const mockLookupRecords = (repo: string, paths: string[]): Record[] => [];
+
+  const result = await withRecordContext(
+    "my-repo",
+    {
+      toolName: "Read",
+      params: { file_path: "src/config.ts" },
+    },
+    mockLookupRecords,
+    async () => {
+      // This is where the actual tool work happens
+      return "file contents here";
+    }
+  );
+
+  console.log("Tool result:", result.output);
+  console.log("Associated records:", result.records);
+};
