+import { injectForPath } from "./inject.ts";
+import type { ToolExecution } from "./extract-paths.ts";
+import { recordToolExecution } from "./query.ts";
+import { recordsForPath } from "./query.ts";
+import type { Record } from "./project.ts";
+
+export interface API {
+  // Hook-based injection (for editors that support pre-tool-use hooks)
+  injectRecords(repo: string, filePath: string): string | null;
+
+  // On-demand queries (works for everyone, with or without hooks)
+  queryRecords(repo: string, filePath: string): readonly Record[];
+
+  // Tool execution reporting (for collecting path data from tool usage)
+  reportToolExecution(
+    repo: string,
+    execution: ToolExecution,
+    lookupRecords: (repo: string, paths: string[]) => Record[]
+  ): void;
+
+  // Batch query (convenience for tools that touch multiple files)
+  queryRecordsBatch(repo: string, filePaths: string[]): Map<string, Record[]>;
+}
+
+export const createAPI = (): API => {
+  return {
+    injectRecords: (repo: string, filePath: string): string | null => {
+      return injectForPath(repo, filePath);
+    },
+
+    queryRecords: (repo: string, filePath: string): readonly Record[] => {
+      return recordsForPath(repo, filePath);
+    },
+
+    reportToolExecution: (
+      repo: string,
+      execution: ToolExecution,
+      lookupRecords: (repo: string, paths: string[]) => Record[]
+    ): void => {
+      recordToolExecution(repo, execution, lookupRecords);
+    },
+
+    queryRecordsBatch: (repo: string, filePaths: string[]): Map<string, Record[]> => {
+      const results = new Map<string, Record[]>();
+      filePaths.forEach((filePath) => {
+        const records = recordsForPath(repo, filePath);
+        if (records.length > 0) {
+          results.set(filePath, Array.from(records));
+        }
+      });
+      return results;
+    },
+  };
+};
