+export interface ToolExecution {
+  toolName: string;
+  params?: Record<string, unknown>;
+  result?: unknown;
+}
+
+export const extractPathsFromToolExecution = (execution: ToolExecution): string[] => {
+  const paths: Set<string> = new Set();
+
+  const { toolName, params, result } = execution;
+
+  // Explicit path parameters — works across all similar tools
+  if (params) {
+    // file_path parameter (Read, Edit, Write, etc.)
+    if (typeof params.file_path === "string") {
+      paths.add(params.file_path);
+    }
+    // filePath parameter (camelCase variant)
+    if (typeof params.filePath === "string") {
+      paths.add(params.filePath);
+    }
+    // file parameter (some tools)
+    if (typeof params.file === "string") {
+      paths.add(params.file);
+    }
+    // Multiple files in array parameters
+    if (Array.isArray(params.files) && params.files.every((f) => typeof f === "string")) {
+      params.files.forEach((f: string) => paths.add(f));
+    }
+  }
+
+  // Result inference — many tools include path context in output
+  if (typeof result === "object" && result !== null) {
+    if (
+      typeof (result as Record<string, unknown>).file_path === "string" ||
+      typeof (result as Record<string, unknown>).filePath === "string"
+    ) {
+      paths.add(
+        ((result as Record<string, unknown>).file_path ||
+          (result as Record<string, unknown>).filePath) as string
+      );
+    }
+  }
+
+  // Shell command parsing (for bash/shell tool)
+  if (toolName.toLowerCase() === "bash" || toolName.toLowerCase() === "shell") {
+    if (typeof params?.command === "string") {
+      const bashPaths = extractPathsFromBashCommand(params.command);
+      bashPaths.forEach((p) => paths.add(p));
+    }
+  }
+
+  return Array.from(paths);
+};
+
+const extractPathsFromBashCommand = (command: string): string[] => {
+  const paths: Set<string> = new Set();
+
+  // grep -r pattern path_spec
+  const grepMatch = command.match(/grep\s+(?:-\w+\s+)*(.+)\s+(.+?)(?:\s|$)/);
+  if (grepMatch?.[2]) {
+    paths.add(grepMatch[2]);
+  }
+
+  // find path_spec -name pattern
+  const findMatch = command.match(/find\s+([^\s]+)/);
+  if (findMatch?.[1]) {
+    paths.add(findMatch[1]);
+  }
+
+  // cat file, head file, tail file, sed, awk, etc.
+  const fileOpMatch = command.match(/(?:cat|head|tail|sed|awk|vim|nano|emacs)\s+([^\s]+)/);
+  if (fileOpMatch?.[1]) {
+    paths.add(fileOpMatch[1]);
+  }
+
+  // git show path, git log path, git diff path
+  const gitMatch = command.match(/git\s+(?:show|log|diff|blame)\s+([^\s]+)/);
+  if (gitMatch?.[1]) {
+    paths.add(gitMatch[1]);
+  }
+
+  return Array.from(paths);
+};
