+export interface Record {
+  path: string;
+  commits: Commit[];
+}
+
+export interface Commit {
+  hash: string;
+  message: string;
+  author: string;
+  date: Date;
+}
+
+export const project = (records: readonly Record[]): string => {
+  if (records.length === 0) return "";
+  return records
+    .map(
+      (record) =>
+        `# ${record.path}\n` +
+        record.commits
+          .map(
+            (commit) =>
+              `- ${commit.hash.slice(0, 7)} ${commit.message} (${commit.author}, ${commit.date.toISOString()})`
+          )
+          .join("\n")
+    )
+    .join("\n\n");
+};
