@@ -0,0 +1,23 @@
+import type { Record } from "./project.ts";
+
+const store = new Map<string, Record[]>();
+
+export const setRecords = (repo: string, filePath: string, records: Record[]): void => {
+  const key = `${repo}:${filePath}`;
+  store.set(key, records);
+};
+
+export const getRecords = (repo: string, filePath: string): readonly Record[] => {
+  const key = `${repo}:${filePath}`;
+  return store.get(key) ?? [];
+};
+
+export const recordAccess = (
+  repo: string,
+  filePath: string,
+  records: readonly Record[]
+): void => {
+  if (records.length > 0) {
+    setRecords(repo, filePath, Array.from(records));
+  }
+};
