+import type { ToolExecution } from "../core/extract-paths.ts";
+import { createAPI } from "../core/api.ts";
+import type { Record } from "../core/project.ts";
+
+const api = createAPI();
+
+export interface ToolResult {
+  records: Record[];
+  output: unknown;
+}
+
+export const withRecordContext = async (
+  repo: string,
+  execution: ToolExecution,
+  lookupRecords: (repo: string, paths: string[]) => Record[],
+  toolExecutor: () => Promise<unknown>
+): Promise<ToolResult> => {
+  api.reportToolExecution(repo, execution, lookupRecords);
+
+  // Extract paths that will be accessed
+  const { extractPathsFromToolExecution } = await import("../core/extract-paths.ts");
+  const paths = extractPathsFromToolExecution(execution);
+
+  const output = await toolExecutor();
+  const records = api.queryRecordsBatch(repo, paths);
+
+  return {
+    records: Array.from(records.values()).flat(),
+    output,
+  };
+};
